//! Local prompt parser — no API key needed
//! 2,527 aliases → 1,339 real GLB models (Quaternius + KhronosGroup)

use crate::GameIntent;

fn color_from_name(name: &str) -> [f32; 4] {
    match name.to_lowercase().as_str() {
        "red" => [0.9, 0.15, 0.15, 1.0],
        "green" => [0.15, 0.8, 0.2, 1.0],
        "blue" => [0.15, 0.3, 0.9, 1.0],
        "yellow" => [0.95, 0.9, 0.1, 1.0],
        "orange" => [0.95, 0.5, 0.1, 1.0],
        "purple" | "violet" => [0.6, 0.15, 0.9, 1.0],
        "pink" => [0.95, 0.4, 0.7, 1.0],
        "cyan" => [0.1, 0.9, 0.9, 1.0],
        "white" => [0.95, 0.95, 0.95, 1.0],
        "black" | "dark" => [0.1, 0.1, 0.1, 1.0],
        "gold" | "golden" => [0.9, 0.75, 0.1, 1.0],
        "silver" | "gray" | "grey" => [0.7, 0.7, 0.7, 1.0],
        "brown" => [0.5, 0.3, 0.1, 1.0],
        "teal" => [0.1, 0.6, 0.6, 1.0],
        "magenta" => [0.9, 0.1, 0.7, 1.0],
        "lime" => [0.5, 0.9, 0.1, 1.0],
        "navy" => [0.1, 0.1, 0.5, 1.0],
        "maroon" => [0.5, 0.1, 0.1, 1.0],
        "olive" => [0.5, 0.5, 0.1, 1.0],
        "coral" => [1.0, 0.5, 0.3, 1.0],
        "turquoise" => [0.25, 0.88, 0.82, 1.0],
        "crimson" => [0.86, 0.08, 0.24, 1.0],
        "indigo" => [0.29, 0.0, 0.51, 1.0],
        "ivory" | "cream" => [0.93, 0.93, 0.88, 1.0],
        "lavender" => [0.71, 0.49, 0.86, 1.0],
        _ => [0.7, 0.7, 0.7, 1.0],
    }
}

