fn build_space_station() -> Vec<GameIntent> {
    let mut v = Vec::new();
    // Main structure (towers as modules)
    v.push(m("core_module", "tower", [0.0, 2.0, 0.0], 3.0));
    v.push(m("hab_module_1", "tower", [-5.0, 2.0, 0.0], 2.0));
    v.push(m("hab_module_2", "tower", [5.0, 2.0, 0.0], 2.0));
    v.push(m("lab_module", "tower", [0.0, 2.0, -5.0], 2.5));
    // Solar panels (planes)
    for (i, (x, z)) in [(-8.0, 3.0), (8.0, 3.0), (-8.0, -3.0), (8.0, -3.0)].iter().enumerate() {
        v.push(GameIntent::AddEntity { name: format!("solar_{}", i), mesh: "plane".into(),
            position: [*x, 4.0, *z], color: [0.1, 0.15, 0.4, 1.0], scale: 2.0 });
    }
    // Robots as crew
    v.push(m("crew_1", "robot", [-2.0, 0.0, 1.0], 0.0));
    v.push(m("crew_2", "robot", [2.0, 0.0, -1.0], 0.0));
    // Satellites (small spheres)
    for i in 0..3 {
        let angle = i as f32 * std::f32::consts::TAU / 3.0;
        v.push(GameIntent::AddEntity { name: format!("satellite_{}", i), mesh: "sphere".into(),
            position: [angle.cos() * 12.0, 6.0, angle.sin() * 12.0], color: [0.8, 0.8, 0.85, 1.0], scale: 0.5 });
    }
    v.push(m("antenna", "lantern", [0.0, 6.0, 0.0], 0.5));
    v.push(m("cargo_crate_1", "crate", [3.0, 0.0, 2.0], 2.0));
    v.push(m("cargo_crate_2", "crate", [-3.0, 0.0, 2.0], 2.0));
    v.push(GameIntent::ChatResponse { message: "🚀 Space station! Core module, habitats, solar panels, robots, satellites, and cargo.".into() });
    v
}

