fn build_gym() -> Vec<GameIntent> {
    let mut v = Vec::new();
    // Benches for weight lifting
    v.push(m("bench_press", "bench", [-3.0, 0.0, 0.0], 2.0));
    v.push(m("bench_press_2", "bench", [3.0, 0.0, 0.0], 2.0));
    // Dumbbells (barrels)
    for i in 0..6 {
        v.push(m(&format!("dumbbell_{}", i), "barrel", [-5.0 + i as f32 * 2.0, 0.3, -3.0], 0.8));
    }
    // Treadmill area (tables as treadmills)
    for i in 0..3 {
        v.push(m(&format!("treadmill_{}", i), "table", [-3.0 + i as f32 * 3.0, 0.0, 4.0], 0.0));
    }
    // People working out
    v.push(m("athlete_1", "man", [-3.0, 0.0, 0.5], 0.0));
    v.push(m("athlete_2", "michelle", [3.0, 0.0, 0.5], 0.0));
    v.push(m("athlete_3", "man", [0.0, 0.0, 4.0], 0.0));
    // Mirror wall (plane)
    v.push(GameIntent::AddEntity { name: "mirror_wall".into(), mesh: "plane".into(),
        position: [0.0, 2.0, -5.0], color: [0.7, 0.75, 0.8, 0.3], scale: 5.0 });
    // Water bottles
    v.push(m("water_1", "bottle", [-4.0, 0.3, 2.0], 0.4));
    v.push(m("water_2", "bottle", [4.0, 0.3, 2.0], 0.4));
    v.push(m("boombox_gym", "boombox", [5.0, 0.0, -3.0], 0.3));
    v.push(GameIntent::ChatResponse { message: "💪 Gym! Benches, dumbbells, treadmills, athletes, mirror wall, and a boombox.".into() });
    v
}
